.callout p { color: #d3ded9; margin:0; }
.bar-chart { display: grid; gap: clamp(.33rem, .58vw, .58rem); margin-top: clamp(.4rem, .8vw, .8rem); }
.bar-row { display: grid; grid-template-columns: minmax(6.8rem, 27%) 1fr minmax(3rem, 4.5rem); gap: clamp(.45rem, .8vw, .8rem); align-items:center; }
.bar-label, .bar-value { font: 700 clamp(.54rem, .82vw, .86rem)/1.1 'Trebuchet MS', Verdana, sans-serif; color: var(--ink); }
.track { height: clamp(.5rem, .95vw, .95rem); background: rgba(23,32,39,.09); border-radius: 999px; overflow:hidden; }
.fill { height:100%; border-radius: 999px; background: linear-gradient(90deg, var(--green), var(--orange)); }
.stacked { height: clamp(2.1rem, 4.2vw, 4.3rem); display:flex; overflow:hidden; border-radius: clamp(.65rem, 1vw, 1rem); border: 1px solid rgba(23,32,39,.12); margin: clamp(.7rem, 1vw, 1rem) 0 clamp(.4rem, .8vw, .8rem); }
.seg { height:100%; display:flex; align-items:center; justify-content:center; color:white; font:700 clamp(.52rem,.75vw,.78rem)/1 'Trebuchet MS', Verdana, sans-serif; min-width: 2rem; }
.legend { display:flex; flex-wrap:wrap; gap: clamp(.35rem, .7vw, .7rem); }
.legend span { font:700 clamp(.48rem,.68vw,.72rem)/1.1 'Trebuchet MS', Verdana, sans-serif; color:var(--muted); text-transform: uppercase; letter-spacing:.04em; }
.legend i { display:inline-block; width: .7em; height:.7em; border-radius: 2px; margin-right:.35em; vertical-align:-.04em; }
.trend { display:grid; grid-template-columns: repeat(3, 1fr); align-items:end; gap: clamp(.7rem, 1.5vw, 1.5rem); height: clamp(17rem, 38vh, 26rem); padding: clamp(.6rem, 1vw, 1rem) clamp(.5rem, 1vw, 1rem) 0; border-bottom: 1px solid rgba(23,32,39,.18); }
.year { height:100%; display:grid; grid-template-rows: 1fr auto; gap: clamp(.35rem, .65vw, .65rem); }
.columns { display:flex; align-items:end; justify-content:center; gap: clamp(.22rem, .45vw, .45rem); height:100%; }
.col { width: clamp(1.2rem, 2vw, 2.2rem); border-radius: .3rem .3rem 0 0; display:flex; align-items:flex-start; justify-content:center; padding-top: .25rem; color:white; font:700 clamp(.45rem,.62vw,.66rem)/1 'Trebuchet MS', Verdana, sans-serif; }
.year-label { text-align:center; font:700 clamp(.65rem,.9vw,.95rem)/1 'Trebuchet MS', Verdana, sans-serif; color: var(--ink); }
.scatter-wrap { height: min(59vh, 37rem); display:grid; grid-template-columns: 1fr minmax(11rem, 16rem); gap: clamp(.8rem,1.4vw,1.4rem); align-items:stretch; }
.scatter { position:relative; background: rgba(255,255,255,.48); border:1px solid rgba(23,32,39,.14); border-radius: clamp(.8rem,1.3vw,1.3rem); overflow:hidden; }
.scatter::before { content:''; position:absolute; inset:8% 8% 12% 10%; background-image: linear-gradient(rgba(23,32,39,.09) 1px, transparent 1px), linear-gradient(90deg, rgba(23,32,39,.09) 1px, transparent 1px); background-size: 25% 25%; border-left: 2px solid rgba(23,32,39,.34); border-bottom: 2px solid rgba(23,32,39,.34); }
.dot { position:absolute; left: calc(10% + var(--x) * 82%); bottom: calc(12% + var(--y) * 80%); transform: translate(-50%, 50%); width: clamp(.42rem,.8vw,.8rem); height: clamp(.42rem,.8vw,.8rem); border-radius:50%; background: var(--c, var(--green)); box-shadow: 0 0 0 clamp(.1rem,.18vw,.18rem) rgba(255,250,240,.9), 0 .18rem .7rem rgba(23,32,39,.24); }
.dot.lg { width: clamp(.6rem,1vw,1.05rem); height: clamp(.6rem,1vw,1.05rem); }
.dot-label { position:absolute; left: calc(10% + var(--x) * 82%); bottom: calc(12% + var(--y) * 80% + .85rem); transform: translateX(-50%); font:700 clamp(.42rem,.62vw,.66rem)/1 'Trebuchet MS', Verdana, sans-serif; color: var(--ink); background: rgba(255,250,240,.78); padding: .12em .3em; border-radius:.3em; white-space:nowrap; }
.axis-x, .axis-y { position:absolute; font:700 clamp(.5rem,.68vw,.72rem)/1 'Trebuchet MS', Verdana, sans-serif; color: var(--muted); text-transform:uppercase; letter-spacing:.06em; }
.axis-x { left:37%; bottom:2.5%; } .axis-y { transform: rotate(-90deg); left:-2.5%; top:45%; }
.note-list { margin:0; padding-left: clamp(.9rem, 1.3vw, 1.3rem); }
.note-list li { margin-bottom: clamp(.45rem, .8vw, .8rem); color: var(--ink); }
.note-list strong { color: var(--green); }
.size-grid { display:grid; grid-template-columns: 1.2fr .8fr; gap: clamp(1rem,2vw,2rem); height:100%; max-height:min(61vh,38rem); }
.size-bars { display:grid; gap: clamp(.25rem,.45vw,.48rem); margin-top:clamp(.3rem,.7vw,.7rem); }
.pill { display:inline-block; padding: .35em .6em; background: rgba(31,111,91,.13); color: var(--green); border-radius:999px; font:700 clamp(.5rem,.72vw,.76rem)/1 'Trebuchet MS', Verdana, sans-serif; text-transform:uppercase; letter-spacing:.05em; }
.takeaways { display:grid; grid-template-columns: repeat(5, 1fr); gap: clamp(.65rem,1.1vw,1.1rem); height: min(56vh, 34rem); align-items:stretch; }
.take-card { background: rgba(255,250,240,.84); border:1px solid rgba(23,32,39,.13); border-top: clamp(.22rem,.42vw,.42rem) solid var(--green); border-radius: clamp(.75rem,1.2vw,1.2rem); padding: clamp(.65rem,1.1vw,1.1rem); box-shadow: 0 .3rem 1.2rem rgba(23,32,39,.08); }
.take-card b { display:block; font:700 clamp(.78rem,1.05vw,1.08rem)/1.1 Georgia,serif; letter-spacing:-.02em; margin-bottom:clamp(.35rem,.55vw,.55rem); }
.take-card p { margin:0; font-size:clamp(.62rem,.86vw,.9rem); }
@media (max-height:700px) { .scatter-wrap{height:min(56vh,32rem)} .trend{height:34vh} .takeaways{height:52vh} }
@media (max-height:600px) { h2{font-size:clamp(1.25rem,2.35vw,2.4rem)} .metric-row{gap:.45rem}.panel{padding:.7rem}.scatter-wrap{height:53vh}.takeaways{height:50vh} }
@media (max-height:500px) { .source, footer{font-size:.45rem}.bar-chart{gap:.22rem}.scatter-wrap{height:50vh}.take-card{padding:.5rem} }
